import * as Core from './core.js';
export async function identityPage(front,back,{landscape=false,margin=90}={}){const canvas=Core.makeCanvas(landscape?3508:2480,landscape?2480:3508),ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);const cardWidth=Math.min(canvas.width-2*margin,Math.round(85.6/210*2480)),cardHeight=cardWidth/1.586;for(const [index,blob]of [front,back].entries()){const bitmap=await Core.image(blob);try{const r=Core.fitRect(bitmap.width,bitmap.height,{x:(canvas.width-cardWidth)/2,y:margin+index*(cardHeight+margin),w:cardWidth,h:cardHeight});ctx.drawImage(bitmap,r.x,r.y,r.w,r.h);}finally{bitmap.close();}}return canvas;}
export async function splitBook(blob,{center=.5,rtl=true,clean=false}={}){if(!Number.isFinite(center)||center<.15||center>.85)throw Error('خط المنتصف خارج الحدود');const pages=await Core.splitPage(blob,true,[center],rtl);if(!clean)return pages;const scanner=await import('./scanner.js');const result=[];for(const c of pages)result.push(await scanner.cleanBackground(await Core.toBlob(c)));return result;}
export async function findBookCenter(blob){const bitmap=await Core.image(blob);try{const canvas=Core.makeCanvas(300,Math.max(80,300*bitmap.height/bitmap.width)),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const {data}=ctx.getImageData(0,0,canvas.width,canvas.height);let best=.5,minimum=Infinity;for(let x=105;x<195;x++){let sum=0;for(let y=Math.floor(canvas.height*.12);y<canvas.height*.88;y++){const i=(y*300+x)*4;sum+=(data[i]+data[i+1]+data[i+2])/3;}const penalized=sum+Math.abs(x-150)*canvas.height*.25;if(penalized<minimum){minimum=penalized;best=x/300;}}return best;}finally{bitmap.close();}}
export async function stampPage(blob,{text,location='',position='bottom'}={}){const bitmap=await Core.image(blob);try{const canvas=Core.makeCanvas(bitmap.width,bitmap.height),ctx=canvas.getContext('2d');ctx.drawImage(bitmap,0,0);const size=Math.max(18,Math.round(canvas.width*.022)),padding=size*.6,height=size*2.6;ctx.fillStyle='rgba(255,255,255,.88)';const y=position==='top'?0:canvas.height-height;ctx.fillRect(0,y,canvas.width,height);ctx.fillStyle='#263c66';ctx.font=`${size}px sans-serif`;ctx.textAlign='right';ctx.direction='rtl';ctx.fillText(String(text||'').slice(0,120),canvas.width-padding,y+size*1.1,canvas.width-padding*2);if(location)ctx.fillText(String(location).slice(0,150),canvas.width-padding,y+size*2.15,canvas.width-padding*2);return canvas;}finally{bitmap.close();}}
export async function passportSheet(blob,{widthMM=35,heightMM=45,copies=6,background='#ffffff'}={}){if(!(widthMM>=20&&widthMM<=100&&heightMM>=20&&heightMM<=100&&copies>=1&&copies<=12))throw Error('مقاس أو عدد صور غير صالح');const bitmap=await Core.image(blob);try{const canvas=Core.makeCanvas(2480,3508),ctx=canvas.getContext('2d'),w=Math.round(widthMM/25.4*300),h=Math.round(heightMM/25.4*300),gap=40,cols=Math.floor((canvas.width-120)/(w+gap));if(cols<1||Math.ceil(copies/cols)*(h+gap)>canvas.height-120)throw Error('الصور لا تتسع في صفحة A4');ctx.fillStyle=background;ctx.fillRect(0,0,canvas.width,canvas.height);const ratio=Math.max(w/bitmap.width,h/bitmap.height),sourceW=w/ratio,sourceH=h/ratio;for(let i=0;i<copies;i++){const x=60+(i%cols)*(w+gap),y=60+Math.floor(i/cols)*(h+gap);ctx.drawImage(bitmap,(bitmap.width-sourceW)/2,(bitmap.height-sourceH)/2,sourceW,sourceH,x,y,w,h);ctx.strokeStyle='#bec8d9';ctx.lineWidth=1;ctx.strokeRect(x,y,w,h);}return canvas;}finally{bitmap.close();}}
export async function megaPage(pages,{axis='vertical',overlap=.15,width=1600}={}){if(pages.length<2||pages.length>12||!Number.isFinite(overlap)||overlap<0||overlap>.5)throw Error('اختر من صورتين إلى 12 صورة وتداخلاً بين 0 و50٪');const dims=pages.map(p=>({w:width,h:Math.round(p.height/p.width*width)}));let w=axis==='vertical'?width:dims.reduce((n,d)=>n+d.w*(1-overlap),0)+width*overlap,h=axis==='vertical'?dims.reduce((n,d)=>n+d.h*(1-overlap),0)+dims.at(-1).h*overlap:Math.max(...dims.map(d=>d.h));if(w*h>18000000||w>16000||h>16000)throw Error('النتيجة كبيرة؛ قلّل عدد الأجزاء أو عرض الصورة');const canvas=Core.makeCanvas(w,h),ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,w,h);let offset=0;for(let i=0;i<pages.length;i++){const bitmap=await Core.image(pages[i].blob);try{ctx.drawImage(bitmap,axis==='vertical'?0:offset,axis==='vertical'?offset:0,dims[i].w,dims[i].h);}finally{bitmap.close();}offset+=(axis==='vertical'?dims[i].h:dims[i].w)*(1-overlap);}return canvas;}
export async function longImages(pages,{width=900}={}){if(!Number.isFinite(width)||width<300||width>1600)throw Error('عرض غير صالح');const result=[];let group=[],height=0;async function flush(){if(!group.length)return;const canvas=Core.makeCanvas(width,height),ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,width,height);let y=0;for(const {page,h}of group){const bitmap=await Core.image(page.blob);try{ctx.drawImage(bitmap,0,y,width,h);}finally{bitmap.close();}y+=h;}result.push(await Core.toBlob(canvas,'image/jpeg',.88));canvas.width=canvas.height=1;group=[];height=0;}for(const page of pages){const h=Math.round(page.height/page.width*width);if(h>12000)throw Error('صفحة طويلة جداً؛ قسّمها أولاً');if(height+h>12000)await flush();group.push({page,h});height+=h;}await flush();return result;}
export function applyRepairRect(canvas,rect,color=null){
 const ctx=canvas.getContext('2d'),{x,y,w,h}=rect;if(![x,y,w,h].every(Number.isInteger)||w<=0||h<=0||x<0||y<0||x+w>canvas.width||y+h>canvas.height)throw Error('منطقة الإصلاح خارج الصورة');
 if(!color){let sums=[0,0,0],count=0;const sample=(sx,sy,sw,sh)=>{const data=ctx.getImageData(sx,sy,sw,sh).data;for(let i=0;i<data.length;i+=4){for(let c=0;c<3;c++)sums[c]+=data[i+c];count++;}};
 if(y>0)sample(x,y-1,w,1);if(y+h<canvas.height)sample(x,y+h,w,1);if(x>0)sample(x-1,y,1,h);if(x+w<canvas.width)sample(x+w,y,1,h);if(!count)throw Error('اترك جزءاً من الخلفية خارج التحديد أو اختر لوناً يدوياً');color=`rgb(${sums.map(v=>Math.round(v/count)).join(',')})`;}
 ctx.fillStyle=color;ctx.fillRect(x,y,w,h);return canvas;
}
export async function repairImage(blob,rect,color=null){const bitmap=await Core.image(blob);try{const canvas=Core.makeCanvas(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,0,0);return applyRepairRect(canvas,rect,color);}finally{bitmap.close();}}


export function detectBookSeam(canvas,axis='vertical'){
 const ctx=canvas.getContext('2d',{willReadFrequently:true}),{data}=ctx.getImageData(0,0,canvas.width,canvas.height),n=axis==='vertical'?canvas.width:canvas.height,m=axis==='vertical'?canvas.height:canvas.width,profile=[];
 for(let a=0;a<n;a++){let sum=0,count=0;for(let b=Math.floor(m*.12);b<m*.88;b++){const x=axis==='vertical'?a:b,y=axis==='vertical'?b:a,i=(y*canvas.width+x)*4;sum+=(data[i]+data[i+1]+data[i+2])/3;count++;}profile.push(sum/Math.max(count,1));}
 let best=.5,score=0;const radius=Math.max(3,Math.round(n*.035));for(let a=Math.floor(n*.2);a<n*.8;a++){const local=(profile[a-1]+profile[a]+profile[a+1])/3,neighbor=(profile[Math.max(0,a-radius)]+profile[Math.min(n-1,a+radius)])/2,difference=neighbor-local,rank=difference-Math.abs(a/n-.5)*20;if(rank>score){score=rank;best=a/n;}}
 return {center:best,confidence:Math.max(0,Math.min(.95,score/45))};
}
export async function detectBookSpread(blob,axis='vertical'){const bitmap=await Core.image(blob);try{const scale=300/Math.max(bitmap.width,bitmap.height),canvas=Core.makeCanvas(bitmap.width*scale,bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const seam=detectBookSeam(canvas,axis);try{const scanner=await import('./scanner.js'),edges=await scanner.detectCanvas(canvas);return {...seam,bounds:edges.confidence>.74?edges.points:null};}catch{return {...seam,bounds:null};}}finally{bitmap.close();}}
